    static
    {
        final BufferedImage arrowDown = ImageUtil.loadImageResource(ShootingStarTrackingPlugin.class, "/arrow.png");
        final BufferedImage arrowUp = ImageUtil.rotateImage(arrowDown,Math.PI);
        ARROW_UP = new ImageIcon(arrowUp);

